from collections import deque
def components(cells):
    cells=set(cells); seen=set(); comps=[]
    for c in cells:
        if c in seen: continue
        q=deque([c]); seen.add(c); comp=[]
        while q:
            i,j=q.popleft(); comp.append((i,j))
            for di in(-1,0,1):
                for dj in(-1,0,1):
                    n=(i+di,j+dj)
                    if n in cells and n not in seen: seen.add(n); q.append(n)
        comps.append(comp)
    return comps

